import type { XldbSchema, XldbUpsertKey } from "./xldb-schema.js";

export type XldbConfig<Schema extends XldbSchema, UpsertKey extends XldbUpsertKey<Schema>> = {
	type: "managed";
	/** The create-only user-facing table name. User renames are preserved. */
	initialTitle: string;
	/** The ordered, non-empty scalar columns used to address rows. */
	upsertKey: UpsertKey;
	schema: Schema;
};

export type Xldb<
	Schema extends XldbSchema = XldbSchema,
	UpsertKey extends XldbUpsertKey<Schema> = XldbUpsertKey<Schema>,
> = {
	_tag: "xldb";
	name: string;
	config: XldbConfig<Schema, UpsertKey>;
};

/**
 * Declare an XLDB table managed by a Worker.
 *
 * @example
 * ```ts
 * import { createXldb } from "@notionhq/workers/alpha/xldb";
 * import * as XldbSchema from "@notionhq/workers/alpha/xldb-schema";
 *
 * export const events = createXldb("events", {
 *   type: "managed",
 *   initialTitle: "Events",
 *   upsertKey: ["externalId"],
 *   schema: {
 *     columns: [
 *       { name: "externalId", title: "External ID", type: XldbSchema.text() },
 *       { name: "occurredAt", title: "Occurred At", type: XldbSchema.timestamp() },
 *       { name: "metadata", title: "Metadata", type: XldbSchema.json() },
 *     ],
 *   },
 * });
 * ```
 */
export function createXldb<
	const Schema extends XldbSchema,
	const UpsertKey extends XldbUpsertKey<Schema>,
>(name: string, config: XldbConfig<Schema, UpsertKey>): Xldb<Schema, UpsertKey> {
	if (!name || typeof name !== "string") {
		throw new Error("XLDB name must be a non-empty string");
	}

	return { _tag: "xldb", name, config };
}
